V21_CSS = r'''\n<style id="maxess-v21-authority-css">\n#maxess-results-10.v21-live .v21-naya{display:flex;align-items:center;gap:18px;max-width:980px;margin:0 auto;padding:24px 26px;border:1px solid rgba(255,255,255,.12);border-radius:28px;background:linear-gradient(135deg,rgba(255,255,255,.07),rgba(166,108,255,.10));box-shadow:0 18px 60px rgba(0,0,0,.28)}\n#maxess-results-10.v21-live .v21-avatar{width:72px;height:72px;border-radius:50%;object-fit:cover;flex:0 0 auto;border:1px solid rgba(255,255,255,.22);box-shadow:0 0 0 5px rgba(166,108,255,.10),0 16px 38px rgba(0,0,0,.30)}\n#maxess-results-10.v21-live .v21-naya-copy{min-width:0;flex:1}.v21-kicker{display:block;color:#d0a8ff;font-size:10px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}.v21-naya-copy p{margin:5px 0 0;color:rgba(255,255,255,.78);font-size:15px}.v21-naya-copy strong{color:#fff}.v21-listen{appearance:none;border:1px solid rgba(208,168,255,.45);border-radius:17px;min-height:54px;padding:0 20px;background:#050507;color:#fff;font-weight:900;letter-spacing:.04em;box-shadow:inset 0 0 0 1px rgba(255,255,255,.08),0 9px 24px rgba(0,0,0,.35);cursor:pointer;transition:.2s ease}.v21-listen:hover{transform:translateY(-2px);box-shadow:inset 0 0 0 1px rgba(255,255,255,.13),0 14px 30px rgba(0,0,0,.42)}.v21-listen:focus-visible{outline:2px solid #d0a8ff;outline-offset:3px}.v21-listen:active{transform:translateY(1px)}\n#maxess-results-10.v21-live .v21-dim-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-top:24px}#maxess-results-10.v21-live .v21-dim-orb{appearance:none;min-height:210px;border:1px solid rgba(255,255,255,.13);border-radius:50%;background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.18),transparent 10%),radial-gradient(circle at 50% 52%,rgba(166,108,255,.18),transparent 48%),#07060b;color:#fff;display:grid;place-items:center;align-content:center;text-align:center;padding:24px;cursor:pointer;box-shadow:inset 0 0 0 1px rgba(255,255,255,.05),0 22px 50px rgba(0,0,0,.28);transition:.22s ease}.v21-dim-orb:hover,.v21-dim-orb:focus-visible{transform:translateY(-5px);border-color:rgba(208,168,255,.45);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08),0 26px 55px rgba(0,0,0,.35)}.v21-dim-score{display:block;font-size:54px;line-height:.8;font-weight:900;letter-spacing:-.07em}.v21-dim-name{display:block;margin-top:14px;font-size:11px;font-weight:900;letter-spacing:.10em;text-transform:uppercase;color:#d0a8ff}.v21-detail{margin-top:18px;padding:20px 22px;border-radius:18px;background:#050507;color:#fff;border:1px solid rgba(208,168,255,.18)}.v21-detail b{display:block;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#d0a8ff}.v21-detail p{margin:8px 0 0;color:rgba(255,255,255,.74);line-height:1.6}\n#maxess-results-10.v21-live .v21-report{margin-top:22px;padding:clamp(28px,4vw,54px);border-radius:30px;background:linear-gradient(135deg,#fff,#f5f2fa);color:#17131d;border:1px solid rgba(25,15,35,.10);box-shadow:0 25px 80px rgba(0,0,0,.12)}.v21-report-kicker{font-size:10px;font-weight:900;letter-spacing:.18em;color:#7042aa}.v21-report h3{margin:8px 0 0;font-size:clamp(34px,4.2vw,58px);line-height:.96;letter-spacing:-.05em}.v21-report p{max-width:760px;color:#4d4754;line-height:1.7;font-size:16px}.v21-report-stage{display:inline-flex;margin-top:12px;padding:9px 13px;border-radius:999px;background:#120a18;color:#fff;font-size:10px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.v21-report-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:22px}.v21-report-cell{padding:16px 18px;border:1px solid rgba(25,15,35,.10);border-radius:16px;background:rgba(255,255,255,.72)}.v21-report-cell span{display:block;font-size:9px;font-weight:900;letter-spacing:.14em;color:#7042aa}.v21-report-cell b{display:block;margin-top:6px;font-size:14px}.v21-report-cell small{display:block;margin-top:5px;color:#6a6470;line-height:1.45}\n#maxess-results-10.v21-live .mx-score-orb{display:grid!important;place-items:center!important}.v21-score-lock{position:relative;z-index:4;text-align:center}.v21-score-lock strong{display:block;font-size:clamp(92px,12vw,156px);line-height:.76;letter-spacing:-.09em;font-weight:950;color:#fff}.v21-score-lock span{display:block;margin-top:17px;color:#d0a8ff;font-size:10px;font-weight:900;letter-spacing:.20em;text-transform:uppercase}\n#maxess-results-10.v21-live .v21-hide{display:none!important}\n@media(max-width:1000px){#maxess-results-10.v21-live .v21-dim-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){#maxess-results-10.v21-live .v21-naya{align-items:flex-start;flex-wrap:wrap}#maxess-results-10.v21-live .v21-listen{width:100%}#maxess-results-10.v21-live .v21-dim-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.v21-report-grid{grid-template-columns:1fr}}@media(max-width:430px){#maxess-results-10.v21-live .v21-dim-grid{grid-template-columns:1fr}.v21-dim-orb{width:min(220px,78vw);justify-self:center}}\n@media print{#maxess-results-10.v21-live .v21-naya{break-inside:avoid;background:#fff!important;color:#111!important;border:1px solid #ddd;box-shadow:none}.v21-listen{display:none!important}.v21-report{break-inside:avoid}.v21-report-grid{grid-template-columns:repeat(3,1fr)}}\n</style>\n'''

V21_JS = r'''\n<script id="maxess-results-v21-authority-js">\n(function(){\n'use strict';\nfunction boot(){\n const root=document.getElementById('maxess-results-10'); if(!root||root.dataset.v21Authority==='1') return; root.dataset.v21Authority='1'; root.classList.add('v21-live');\n const R=()=>window.MAXESS_RESULT||{}; const clamp=x=>Math.max(0,Math.min(100,Number(x)||0)); const score=()=>clamp(R().overallScore??R().masterScore??R().score);\n const dims=()=>Array.isArray(R().dimensions)?R().dimensions.slice(0,5).map((d,i)=>({name:String(d.name||d.label||['Direction','Communication','Evaluation','Iteration','Systems Thinking'][i]),score:clamp(d.score??d.value)})):[];\n const ds=dims(); const s=Math.round(score());\n const stage=s>=91?'Mastering':s>=76?'Advancing':s>=51?'Developing':'Foundation';\n const rootSections=[...root.querySelectorAll('section')];\n const find=(terms)=>rootSections.find(sec=>terms.some(t=>(sec.textContent||'').toLowerCase().includes(t.toLowerCase())));\n // Hide competing V11/V13/V18/V20 top shells, but preserve their useful descendant sections.\n root.querySelectorAll('.v18-naya-top,.v11-naya-welcome,.v11-naya-panel,.v12-naya-intro,.v13-naya-introduction,.v20-naya').forEach(e=>e.classList.add('v21-hide'));\n // Naya guide\n const hero=root.querySelector('.mx-hero');\n if(hero && !root.querySelector('.v21-naya')){\n   const n=document.createElement('section'); n.className='mx-section v21-naya';\n   n.innerHTML='<img class="v21-avatar" src="https://raw.githubusercontent.com/SoulSchoolAcademy/maxess/main/Naya%20Profile%20Black.jpg" alt="Naya, your AI guide"><div class="v21-naya-copy"><span class="v21-kicker">NAYA · YOUR AI GUIDE</span><p><strong>Hi. I’ve looked at your results.</strong><br>This isn’t your judgment. It’s your map.</p></div><button class="v21-listen" type="button">LISTEN TO NAYA <span aria-hidden="true">▶</span></button>';
   hero.parentNode.insertBefore(n,hero.nextSibling);\n   n.querySelector('.v21-listen').addEventListener('click',()=>{const c=[...root.querySelectorAll('#mx-naya-listen,#v11-naya-listen,#v13-listen,.mx-naya-listen,.v18-listen')].find(x=>getComputedStyle(x).display!=='none'); if(c)c.click(); else root.dispatchEvent(new CustomEvent('maxess:naya-listen',{bubbles:true,detail:{result:R()}}));});\n }\n // Score lock\n const orb=root.querySelector('.mx-score-orb'); if(orb){ orb.querySelectorAll('.mx-score,.v21-score-lock').forEach(e=>e.classList.add('v21-hide')); const lock=document.createElement('div'); lock.className='v21-score-lock'; lock.innerHTML='<strong>'+s+'</strong><span>MAXESS SCORE</span>'; orb.appendChild(lock); orb.setAttribute('role','img'); orb.setAttribute('aria-label','Your MAXESS score is '+s); }\n // Five dimensions\n let dimSection=find(['your five dimensions','five dimensions','your fingerprint']);\n if(dimSection && ds.length===5){\n   dimSection.id='v21-dimensions';\n   const old=dimSection.querySelector('.v21-dim-grid'); if(old) old.remove();\n   const grid=document.createElement('div'); grid.className='v21-dim-grid'; const detail=document.createElement('div'); detail.className='v21-detail'; detail.innerHTML='<b>SELECT A DIMENSION</b><p>Choose one of the five orbs to explore what this capability means and where its leverage lives.</p>';\n   ds.forEach((d,i)=>{const b=document.createElement('button'); b.type='button'; b.className='v21-dim-orb'; b.setAttribute('aria-label',d.name+' score '+Math.round(d.score)); b.innerHTML='<span class="v21-dim-score">'+Math.round(d.score)+'</span><span class="v21-dim-name">'+d.name+'</span>'; b.addEventListener('click',()=>{detail.innerHTML='<b>'+d.name+' · '+Math.round(d.score)+' / 100</b><p>'+interpret(d.name,d.score)+'</p>'; detail.scrollIntoView({behavior:'smooth',block:'nearest'});}); grid.appendChild(b);});\n   const gridHolder=dimSection.querySelector('.mx-wide')||dimSection; gridHolder.appendChild(grid); gridHolder.appendChild(detail);\n }\n // Personalized report document\n const report=find(['your report','listen to your results','personalized report']);\n if(report){\n   report.id='v21-report'; let doc=report.querySelector('.v21-report'); if(!doc){doc=document.createElement('article');doc.className='v21-report'; const top=ds.slice().sort((a,b)=>b.score-a.score)[0]; const low=ds.slice().sort((a,b)=>a.score-b.score)[0]; doc.innerHTML='<span class="v21-report-kicker">YOUR PERSONALIZED REPORT</span><h3>Here’s what your result tells us.</h3><span class="v21-report-stage">'+stage+'</span><p>Your MAXESS score is '+s+'. That is not a judgment; it is a map of your current AI capability. Your strongest visible dimension is <strong>'+escape(top?.name||'your leading dimension')+'</strong>, while <strong>'+escape(low?.name||'your next lever')+'</strong> offers the clearest opportunity for focused improvement.</p><div class="v21-report-grid"><div class="v21-report-cell"><span>OVERALL RESULT</span><b>'+s+' / 100</b><small>Your current MAXESS score.</small></div><div class="v21-report-cell"><span>MASTERY STAGE</span><b>'+stage+'</b><small>Where your current capability sits.</small></div><div class="v21-report-cell"><span>NEXT LEVER</span><b>'+escape(low?.name||'Focused improvement')+'</b><small>Protect your strength. Build your lever.</small></div></div>'; (report.querySelector('.mx-wide')||report).appendChild(doc);}\n }\n // Remove duplicate visible listen CTAs; keep the V21 authority control.\n root.querySelectorAll('#mx-naya-listen,#v11-naya-listen,#v13-listen,.mx-naya-listen,.v18-listen').forEach(e=>e.classList.add('v21-hide'));\n // Make print intentional.\n root.setAttribute('data-results-version','21-authority'); root.setAttribute('data-results-data-source','window.MAXESS_RESULT'); root.setAttribute('data-v21-score',String(s)); root.setAttribute('data-v21-stage',stage);\n function interpret(name,sc){const n=name.toLowerCase();if(n.includes('communication'))return 'Communication shows how effectively you express intent, context, constraints and desired outcomes. A strong score here can become leverage through reusable briefs and instructions.';if(n.includes('direction'))return 'Direction shows how clearly you define what you want AI to accomplish. Strong direction reduces wasted work and creates better first attempts.';if(n.includes('evaluation'))return 'Evaluation shows how deliberately you judge AI output before accepting it. Improving this creates a powerful quality filter.';if(n.includes('iteration'))return 'Iteration shows how naturally you improve an answer instead of treating the first response as final. This is where quality compounds.';if(n.includes('system'))return 'Systems Thinking shows whether you turn repeated AI work into reusable workflows, assets and leverage.';return 'This dimension is one of the capabilities shaping your overall MAXESS result. Use its score as a signal for focused practice.'}\n function escape(v){return String(v||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'})[c]);}\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,500),{once:true});else setTimeout(boot,500);\n})();\n</script>\n'''

def sha(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()

def main() -> int:
    if not SOURCE.exists() or not BASELINE.exists():
        print('ERROR: source/baseline missing'); return 2
    if sha(SOURCE) != sha(BASELINE):
        print('ERROR: source no longer matches frozen baseline; refusing Packet 2')
        return 3
    text=SOURCE.read_text(encoding='utf-8')
    if 'id="maxess-results-v21-authority-js"' in text:
        print('ERROR: V21 authority already present; refusing duplicate application'); return 4
    insertion=V21_CSS+'\n'+V21_JS
    text=text.replace('</body>', insertion+'\n</body>') if '</body>' in text else text+insertion
    OUT.write_text(text,encoding='utf-8')
    print('V21 PACKET 2 APPLIED')
    print(f'New SHA-256: {sha(OUT)}')
    print(f'Lines: {text.count(chr(10))+1}')
    print('Authoritative V21 layer appended once; baseline preserved.')
    return 0

if __name__=='__main__': raise SystemExit(main())
